    31→
    32→/**
    33→ * We use {@link Verifier} here for mvn executions, mainly so:
    34→ * a) we can verify a few cases that the invoker method make really difficult (I'd like to step-through with my IDE)
    35→ * b) the test harness method requires creating a custom Artifact resolver, as the dependencGraphBuilder Component will
    36→ * not provide a usable bean, and we would need extensive mocking to override data for specific cases
    37→ * c) it's a lot faster than maven-invoker-plugin
    38→ * ... good overview of similar woes <a href="https://khmarbaise.github.io/maven-it-extension/itf-documentation/background/background.html">
    39→ *   https://khmarbaise.github.io/maven-it-extension/itf-documentation/background/background.html</a>
    40→ *
    41→ * @author Royce Remer
    42→ */
    43→class MavenProjectLicensesIT {
    44→
    45→  File source;
    46→  String target;
    47→  String phase;
    48→  Map<String, String> env;
    49→
    50→  @TempDir
    51→  File workspace;
    52→  final String sourcePrefix = "src/test/resources/config/";
    53→  final String resource = "/pom.xml";
    54→
    55→  @BeforeEach
    56→  public void setUp() {
    57→    // your maven may be on a different path, they'll append '/bin/mvn' to it
    58→    System.setProperty("maven.home", "/usr/local");
    59→
    60→    this.target = workspace.getAbsolutePath();
    61→    this.env = Collections.singletonMap("LICENSE_PLUGIN_VERSION", this.getClass().getPackage().getImplementationVersion());
    62→    this.phase = "verify";
    63→  }
    64→
    65→  private boolean hasLogLine(final String logline) {
    66→    Optional<Verifier> verifier;
    67→    try {
    68→      verifier = Optional.of(new Verifier(target));
    69→    } catch (Exception ex) {
    70→      // project didn't even build, this is a test or test resource error
    71→      return false;
    72→    }
    73→
    74→    try {
    75→      verifier.get().executeGoal(phase, env);
    76→    } catch (VerificationException e) {
    77→      // potential purposeful MojoExecutionException (hidden in stack)
    78→      try {
    79→        verifier.get().verifyTextInLog(logline);
    80→        return true;
    81→      } catch (VerificationException e1) {
    82→      }
    83→    }
    84→
    85→    // legit test failure
    86→    return false;
    87→  }
