    90→   * Helper method to sync test resources to a temporary folder for execution.
    91→   *
    92→   * @param dir - String relative path to {@link sourcePrefix} to copy from.
    93→   * @throws IOException
    94→   */
    95→  private void syncTarget(final String dir) throws IOException {
    96→    source = new File(sourcePrefix + dir + resource);
    97→    final File syncTarget = new File(target + resource);
    98→    Files.copy(source, syncTarget);
    99→  }
   100→
   101→  @Test
   102→  void test_null() throws IOException {
   103→    final String description = "A project with enforcement enabled but nothing in scope should find zero dependencies";
   104→    syncTarget("null");
   105→
   106→    Assertions.assertTrue(hasLogLine(LicenseMessage.INFO_DEPS_DISCOVERED + ": 1"), description);
   107→  }
   108→
   109→  @Test
   110→  void test_deny() throws IOException {
   111→    final String description = "A project with enforcement enabled and dependencies in scope under default deny policy should fail.";
