   118→  void test_approved() throws IOException {
   119→    final String description = "A project with allow policy and a single dependency should succeed.";
   120→    syncTarget("approve");
   121→
   122→    Assertions.assertTrue(hasLogLine(LicenseMessage.INFO_DEPS_DISCOVERED + ": 1"), description);
   123→  }
   124→}
